+            let fields = parse_routing_fields(&Bytes::copy_from_slice(body.as_bytes()))
+                .unwrap_or_else(|e| panic!("{body} must still parse: {e:?}"));
+            assert_eq!(fields.model.as_deref(), Some("x"), "{body}");
+        }
